def parse(key,html,*,pid):
    path,heading,specs=SPECS[key]
    root=content(html,heading)
    rules=[]
    courses=[]
    for suffix,title,markers,summary in specs:
        require_phrases(root,markers)
        rules.append(rule(pid+'-policy-'+key+'-'+suffix,title,pid+'-policy-'+key,kind='note',summary=summary))
    if key == 'arhu':
        require_phrases(root,['ARHU158', 'Explorations in the Arts and Humanities'])
        c=course('ARHU158','Explorations in the Arts and Humanities',pid+'-policy-arhu',BASE+path,institution='umd',unit='semester_hours',category='human_context')
        courses.append(c)
        next(r for r in rules if r['id']==pid+'-policy-arhu-college')['course_ids']=[c['id']]
        parent = pid + '-policy-arhu-global-routes'
        rules.append(rule(parent,'Global Engagement: proficiency or one approved route',pid+'-policy-arhu',kind='alternative',summary='Meet the proficiency route or one of the three published alternatives. The routes are not cumulative requirements.'))
        for r in rules:
            if r['id'].rsplit('-',1)[-1] in {'language','abroad','individual'}:
                r['parent_id'] = parent
        rules.append(rule(pid+'-policy-arhu-proficiency','Approved proficiency evidence',pid+'-policy-arhu',parent=parent,kind='note',summary='Approved Maryland Seal of Biliteracy, qualifying documented other-state proficiency, proctored native-language placement or approved outside assessment can fulfill this route. Follow the college’s stated proficiency thresholds and approval process.'))
    return dict(id=pid,requirements=rules,courses=courses)


EXTRA={
 'gened-resources':('https://gened.umd.edu/students/student-resources/','Student Resources', ['minimum of 40 credits in General Education'], 'The official General Education resources page sets a minimum of 40 General Education credits even when approved requirements overlap. Nominal course-category totals are not a substitute for that minimum.'),
 'global':('https://arhu.umd.edu/academics/advising/global-engagement/','GLOBAL ENGAGEMENT', ['Students seeking to fulfill a Gen Ed requirement cannot take the class Pass-Fail', 'minimum 45 hours', 'course sequences'], 'The ARHU language-route Pass-Fail allowance cannot be used for a course also applied to General Education. Other university eligibility and college exclusions still apply. The college page links the exact language-sequence PDF; its public viewer was inspected, but the embedded download was robots-disallowed, so exact sequences are not asserted.'),
 'cmns-advising':('https://cmns.umd.edu/undergraduate/advising-academic-planning/','Declaring a CMNS Major or Minor', ['prior to registering for their last semester', 'officially add a double major/double degree one year prior'], 'CMNS requires membership in the graduating major before final-semester registration and addition of a double major/degree one year before graduation. This page does not name the new AI major in its program-specific declaration groups. Do not automatically assign the separate Computer Science limited-enrollment gateway to AI; AI-specific admission/transition rules remain unverified.'),
}


def parse_extra(key,html,*,pid):
    url,heading,markers,summary=EXTRA[key]
    root=content(html,heading)
    require_phrases(root,markers)
    return dict(id=pid,requirements=[rule(pid+'-policy-'+key,key.replace('-',' ').title(),pid+'-policy-'+key,kind='note',summary=summary)])


def parsers(pid,*,arhu=False):
    result={BASE+spec[0]:partial(parse,key,pid=pid) for key,spec in SPECS.items() if arhu or key!='arhu'}
    for key in ['gened-resources','global' if arhu else 'cmns-advising']:
        result[EXTRA[key][0]]=partial(parse_extra,key,pid=pid)
    return result
